import AxeBuilder from '@axe-core/playwright';
import { expect, test } from '@playwright/test';

const accessibilityPages = [
  '/',
  '/suite/',
  '/suite/preise/',
  '/suite/forge/',
  '/services/',
  '/services/website-kosten/',
  '/semrel/',
  '/blog/',
  '/referenzen/',
  '/kontakt/',
  '/agb/',
  '/widerrufsbelehrung/',
];

test('all sitemap pages use the shared light shell and document structure', async ({
  request,
}) => {
  test.setTimeout(180_000);

  const indexResponse = await request.get('/sitemap-index.xml');
  expect(indexResponse.ok()).toBeTruthy();
  const sitemapIndex = await indexResponse.text();
  const sitemapLocations = Array.from(
    sitemapIndex.matchAll(/<loc>([^<]+)<\/loc>/g),
    (match) => new URL(match[1]).pathname,
  );
  expect(sitemapLocations.length).toBeGreaterThan(0);

  const pagePaths = new Set<string>();
  for (const sitemapPath of sitemapLocations) {
    const sitemapResponse = await request.get(sitemapPath);
    expect(sitemapResponse.ok(), sitemapPath).toBeTruthy();
    const sitemap = await sitemapResponse.text();
    for (const match of sitemap.matchAll(/<loc>([^<]+)<\/loc>/g)) {
      pagePaths.add(new URL(match[1]).pathname);
    }
  }
  expect(pagePaths.size).toBeGreaterThan(30);

  const failures: string[] = [];
  const paths = [...pagePaths];
  for (let offset = 0; offset < paths.length; offset += 20) {
    const batch = await Promise.all(
      paths.slice(offset, offset + 20).map(async (path) => {
        const response = await request.get(path);
        const html = await response.text();
        const imageTags = html.match(/<img\b[^>]*>/gi) ?? [];
        return {
          path,
          status: response.status(),
          titleCount: html.match(/<title\b/gi)?.length ?? 0,
          descriptionCount: (html.match(/<meta\b[^>]*>/gi) ?? []).filter(
            (tag) =>
              /\bname=(?:"description"|'description'|description(?=[\s/>]))/i.test(
                tag,
              ),
          ).length,
          headingCount: html.match(/<h1\b/gi)?.length ?? 0,
          mainCount: html.match(/<main\b/gi)?.length ?? 0,
          missingImageAlt: imageTags.filter(
            (image) =>
              !/\balt(?:=["'][^"']*["']|=[^\s>]+)/i.test(image),
          ).length,
          hasLightTheme:
            /<html\b[^>]*\bdata-theme=(?:"light"|'light'|light(?=[\s/>]))/i.test(
              html,
            ),
        };
      }),
    );

    for (const result of batch) {
      const issues = [
        result.status !== 200 && `HTTP ${result.status}`,
        result.titleCount !== 1 && `title count ${result.titleCount}`,
        result.descriptionCount !== 1 &&
          `description count ${result.descriptionCount}`,
        result.headingCount !== 1 && `h1 count ${result.headingCount}`,
        result.mainCount !== 1 && `main count ${result.mainCount}`,
        result.missingImageAlt > 0 &&
          `${result.missingImageAlt} images without alt`,
        !result.hasLightTheme && 'light theme missing',
      ].filter(Boolean);

      if (issues.length > 0) {
        failures.push(`${result.path}: ${issues.join(', ')}`);
      }
    }
  }

  expect(failures).toEqual([]);
});

test('primary pages pass mobile accessibility and overflow checks', async ({
  page,
}) => {
  await page.setViewportSize({ width: 390, height: 844 });

  for (const path of accessibilityPages) {
    await page.goto(path, { waitUntil: 'domcontentloaded' });
    const overflow = await page.evaluate(() => {
      const overflowingElements = Array.from(
        document.querySelectorAll('body *'),
      )
        .map((element) => {
          const bounds = element.getBoundingClientRect();
          return {
            element,
            left: Math.round(bounds.left),
            right: Math.round(bounds.right),
          };
        })
        .filter(
          ({ left, right }) => left < -1 || right > window.innerWidth + 1,
        )
        .slice(0, 10)
        .map(({ element, left, right }) => ({
          tag: element.tagName,
          id: element.id,
          className: element.getAttribute('class'),
          text: element.textContent?.trim().slice(0, 100),
          left,
          right,
        }));
      return {
        viewportWidth: window.innerWidth,
        documentWidth: document.documentElement.scrollWidth,
        bodyWidth: document.body.scrollWidth,
        hasHorizontalOverflow:
          document.documentElement.scrollWidth > window.innerWidth,
        overflowingElements,
        scrollableElements: Array.from(document.querySelectorAll('body *'))
          .filter((element) => element.scrollWidth > element.clientWidth + 1)
          .slice(0, 10)
          .map((element) => ({
            tag: element.tagName,
            id: element.id,
            className: element.getAttribute('class'),
            clientWidth: element.clientWidth,
            scrollWidth: element.scrollWidth,
            overflowX: getComputedStyle(element).overflowX,
          })),
      };
    });
    expect(
      overflow.hasHorizontalOverflow,
      `${path} has horizontal overflow: ${JSON.stringify(overflow)}`,
    ).toBe(false);

    const accessibility = await new AxeBuilder({ page })
      .withTags(['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa', 'wcag22aa'])
      .analyze();
    expect(accessibility.violations, `${path} accessibility violations`).toEqual(
      [],
    );
  }
});

test('navigation menus expose state and support Escape on desktop and mobile', async ({
  page,
}) => {
  await page.setViewportSize({ width: 1280, height: 900 });
  await page.goto('/');

  const navigation = page.getByRole('navigation', { name: 'Hauptnavigation' });
  const suiteTrigger = navigation.getByRole('button', { name: 'Suite' });
  await suiteTrigger.click();
  await expect(suiteTrigger).toHaveAttribute('aria-expanded', 'true');
  await page.keyboard.press('Escape');
  await expect(suiteTrigger).toHaveAttribute('aria-expanded', 'false');
  await expect(suiteTrigger).toBeFocused();

  await page.setViewportSize({ width: 390, height: 844 });
  const mobileTrigger = navigation.locator('.button-toggle');
  await mobileTrigger.click();
  await expect(mobileTrigger).toHaveAttribute('aria-expanded', 'true');
  await expect(mobileTrigger).toHaveAttribute(
    'aria-label',
    'Hauptmenü schließen',
  );
  const mobileMenu = navigation.getByRole('region', { name: 'Navigation' });
  await expect(mobileMenu).toBeVisible();
  await expect(
    navigation.getByRole('button', { name: 'Menü schließen', exact: true }),
  ).toBeFocused();
  await page.keyboard.press('Escape');
  await expect(mobileMenu).toBeHidden();
  await expect(mobileTrigger).toHaveAttribute('aria-expanded', 'false');
  await expect(mobileTrigger).toBeFocused();
});
